package com.example.ble_throughput_server;
import ej.bluetooth.BluetoothAdapter;
import ej.bluetooth.util.AttributeNotFoundException;
import ej.bluetooth.BluetoothService;
import ej.bluetooth.BluetoothServiceDefinition;
import ej.bluetooth.util.SecurityLevels;

/**
 * Generated by the application template.
 * <p>
 * Please keep it in sync with the property 'applicationEntryPoint' defined in gradle.build.kts.
 */
public class Main {

    public static void main(String[] args) {
        // Enable adapter
        BluetoothAdapter adapter = BluetoothAdapter.getAdapter();
        adapter.enable();

        BluetoothServiceDefinition BLEThroughputDefinition = BLEThroughputConstants.getServiceDefinition(SecurityLevels.NONE);
        BluetoothService service = adapter.addService(BLEThroughputDefinition);
        if (service == null){
            throw new RuntimeException("Could not add serial port service");
        }

        BLEThroughputApp listener = new BLEThroughputApp(service);
        try {
            listener.start();
        } catch (AttributeNotFoundException e) {
            throw new RuntimeException(e);
        }
    }
}